#include "test_framework.h"
#include "core/Crypto.h"
#include <cstring>
#include <string>
#include <vector>

// Known-answer vectors generated by an independent Python transcription of the
// documented key derivation / stream transform (scripts/gen_crypto_kat.py).
// Inputs: name="Game", copyright="", editorFilename="game.exe" (build > 284 order).

TEST(crypto_keystring) {
    // "Game" -> 'G','a','m','e' low bytes only (high bytes are zero).
    auto ks = ctfak::Crypto::keyString("Game");
    std::vector<uint8_t> expected = {'G', 'a', 'm', 'e'};
    EXPECT_BYTES(ks.data(), ks.size(), expected.data(), expected.size());
}

TEST(crypto_make_key_combined) {
    // makeKeyCombined over {0x01, 0x02}: verified against the Python reference.
    std::vector<uint8_t> data = {0x01, 0x02};
    auto out = ctfak::Crypto::makeKeyCombined(data);
    EXPECT_EQ(out.size(), 256);
    EXPECT_EQ(out[0], 0x1A); // 0x01 ^ rotl8(54)=0x1B
    EXPECT_EQ(out[1], 0x8F);
    EXPECT_EQ(out[2], 0xC6);
    EXPECT_EQ(out[3], 0xBD); // rolling checksum byte
}

TEST(crypto_stream_transform_roundtrip) {
    ctfak::Crypto::makeKey("Game", "", "game.exe");
    EXPECT_TRUE(ctfak::Crypto::valid());
    std::vector<uint8_t> payload;
    for (int i = 0; i < 64; ++i) payload.push_back(static_cast<uint8_t>(i));
    std::vector<uint8_t> encrypted = payload;
    ctfak::Crypto::transformChunk(encrypted);

    static const uint8_t expected[64] = {
        0xAD, 0x02, 0xCC, 0x89, 0xDB, 0x1F, 0x48, 0xB1, 0x5F, 0x45, 0xF1, 0xF8, 0x12, 0x4F, 0x41, 0x25,
        0x65, 0x40, 0x6E, 0x5D, 0x6F, 0x0A, 0x6F, 0x1D, 0x8C, 0xD8, 0xC5, 0x45, 0x0A, 0x58, 0xCD, 0xB3,
        0x02, 0xB2, 0x32, 0x79, 0x09, 0x14, 0x17, 0x13, 0x02, 0xA2, 0xF9, 0xFF, 0x2B, 0x43, 0xFD, 0xFA,
        0x8A, 0x31, 0xD4, 0x64, 0x0A, 0xB1, 0x72, 0x99, 0x2B, 0xEE, 0xA6, 0x63, 0x39, 0x6D, 0xFB, 0x9C};
    EXPECT_BYTES(encrypted.data(), encrypted.size(), expected, 64);

    // The transform is an involution over the same key table.
    ctfak::Crypto::transformChunk(encrypted);
    EXPECT_BYTES(encrypted.data(), encrypted.size(), payload.data(), payload.size());
}

TEST(crypto_transform_without_key_is_noop) {
    // A fresh process that never called makeKey must leave data untouched.
    // (Crypto::valid starts false; emulate by transforming an unchanged copy.)
    // Note: this test relies on running before other tests initialized the key,
    // so it only checks the guard function exists and data is unchanged when invalid.
    std::vector<uint8_t> data = {1, 2, 3, 4, 5};
    std::vector<uint8_t> copy = data;
    if (!ctfak::Crypto::valid()) {
        ctfak::Crypto::transformChunk(data);
        EXPECT_BYTES(data.data(), data.size(), copy.data(), copy.size());
    }
}
